diff --git a/lib/curlx/strparse.c b/lib/curlx/strparse.c
index a17aa3c..97267d0 100644
--- a/lib/curlx/strparse.c
+++ b/lib/curlx/strparse.c
@@ -191,7 +191,7 @@ static int str_num_base(const char **linep, curl_off_t *nump, curl_off_t max,
     } while(valid_digit(*p, m));
   }
   else {
-    curl_off_t cutoff = (max - (base - 1)) / base;
+    curl_off_t cutoff = max / base;
     while(valid_digit(*p, m)) {
       if(num <= cutoff)
         num = (num * base) + curlx_hexval(*p++);

diff --git a/lib/mprintf.c b/lib/mprintf.c
index abe0df4..da2ecfd 100644
--- a/lib/mprintf.c
+++ b/lib/mprintf.c
@@ -1009,7 +1009,7 @@ static bool out_string(void *userp,
   /* With no precision, len is already the exact length; emit it without
      scanning again. With precision, scan up to len but stop at NUL, since
      the string may be shorter or the buffer may not be NUL-terminated. */
-  if(prec == -1) {
+  if(prec < 0) {
     if(stream_run(userp, stream, streamn,
                   (const unsigned char *)str, len, donep))
       return TRUE;
